INSERT INTO `actividades_sustantivas` VALUES ('11263','652','9','Gestionar y supervisar la realización del Informe Anual de Actividades.',NULL,NULL,NULL,'0'),
('11264','652','10','Coadyuvar con las coordinaciones y áreas afines en la difusión de sus actividades',NULL,NULL,NULL,'0'),
