INSERT INTO `dimensiones` VALUES ('1','1','Eficacia','Mide el nivel de cumplimiento de los objetivos.'),
('2','1','Eficiencia','Mide la relación entre los productos y servicios generados con respecto a los insumos o recursos utilizados.'),
('3','1','Economía','Mide la capacidad para generar y movilizar adecuadamente los recursos financieros.'),
('4','1','Calidad','Mide los atributos, propiedades o características que deben tener los bienes y servicios para satisfacer los objetivos del proyecto.');
