SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `acciones_equidades_generos`;
CREATE TABLE `acciones_equidades_generos` (
  `accion_equidad_genero_id` int(11) NOT NULL AUTO_INCREMENT,
  `numero` varchar(50) NOT NULL,
  `descripcion` varchar(1024) NOT NULL,
  `status` varchar(15) NOT NULL DEFAULT 'activo',
  PRIMARY KEY (`accion_equidad_genero_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `actividad_riesgo`;
CREATE TABLE `actividad_riesgo` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `actividad_sustantiva_id` int(11) NOT NULL,
  `riesgo_id` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `actividad_riesgo_riesgo_id_foreign` (`riesgo_id`),
  CONSTRAINT `actividad_riesgo_riesgo_id_foreign` FOREIGN KEY (`riesgo_id`) REFERENCES `riesgos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=13557 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `actividades_sustantivas`;
CREATE TABLE `actividades_sustantivas` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `proyecto_id` int(11) NOT NULL,
  `numero` int(11) DEFAULT NULL,
  `descripcion` text NOT NULL,
  `recursos_asociados` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `es_resumida` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `actividades_sustantivas_proyecto_id_foreign` (`proyecto_id`)
) ENGINE=InnoDB AUTO_INCREMENT=51493 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `areas`;
CREATE TABLE `areas` (
  `area_id` int(11) NOT NULL AUTO_INCREMENT,
  `nombre` varchar(255) NOT NULL,
  `descripcion` varchar(255) NOT NULL,
  `estado` varchar(15) NOT NULL DEFAULT 'activo',
  PRIMARY KEY (`area_id`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `cache`;
CREATE TABLE `cache` (
  `key` varchar(255) NOT NULL,
  `value` mediumtext NOT NULL,
  `expiration` bigint(20) NOT NULL,
  PRIMARY KEY (`key`),
  KEY `cache_expiration_index` (`expiration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `cache_locks`;
CREATE TABLE `cache_locks` (
  `key` varchar(255) NOT NULL,
  `owner` varchar(255) NOT NULL,
  `expiration` bigint(20) NOT NULL,
  PRIMARY KEY (`key`),
  KEY `cache_locks_expiration_index` (`expiration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `ci_sessions`;
CREATE TABLE `ci_sessions` (
  `session_id` varchar(40) NOT NULL DEFAULT '0',
  `ip_address` varchar(45) NOT NULL DEFAULT '0',
  `user_agent` varchar(120) NOT NULL,
  `last_activity` int(10) unsigned NOT NULL DEFAULT 0,
  `user_data` text NOT NULL,
  PRIMARY KEY (`session_id`),
  KEY `last_activity_idx` (`last_activity`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


DROP TABLE IF EXISTS `dimensiones`;
CREATE TABLE `dimensiones` (
  `dimension_id` int(11) NOT NULL AUTO_INCREMENT,
  `ejercicio_id` int(11) NOT NULL,
  `nombre` varchar(25) NOT NULL,
  `descripcion` varchar(255) NOT NULL,
  PRIMARY KEY (`dimension_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `ejercicios`;
CREATE TABLE `ejercicios` (
  `ejercicio_id` int(11) NOT NULL AUTO_INCREMENT,
  `ejercicio` int(11) NOT NULL,
  `permitir_edicion_seguimiento` char(2) NOT NULL,
  `permitir_edicion_seguimiento_derechos_humanos` char(2) NOT NULL,
  `permitir_edicion_elaboracion` char(2) NOT NULL,
  `ultimo_mes_visible` varchar(15) NOT NULL,
  `ultimo_mes_consulta` varchar(15) NOT NULL,
  `tipo_captura_seguimiento` varchar(15) NOT NULL,
  PRIMARY KEY (`ejercicio_id`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `ejercicios_anteproyectos`;
CREATE TABLE `ejercicios_anteproyectos` (
  `ejercicio_anteproyecto_id` int(11) NOT NULL AUTO_INCREMENT,
  `ejercicio` int(11) NOT NULL,
  PRIMARY KEY (`ejercicio_anteproyecto_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `equidades_generos`;
CREATE TABLE `equidades_generos` (
  `equidad_genero_id` int(11) NOT NULL AUTO_INCREMENT,
  `proyecto_id` int(11) NOT NULL,
  `accion_equidad_genero_id` int(11) NOT NULL,
  `descripcion` varchar(1024) NOT NULL,
  PRIMARY KEY (`equidad_genero_id`)
) ENGINE=InnoDB AUTO_INCREMENT=131 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `failed_jobs`;
CREATE TABLE `failed_jobs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` varchar(255) NOT NULL,
  `connection` varchar(255) NOT NULL,
  `queue` varchar(255) NOT NULL,
  `payload` longtext NOT NULL,
  `exception` longtext NOT NULL,
  `failed_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `failed_jobs_uuid_unique` (`uuid`),
  KEY `failed_jobs_connection_queue_failed_at_index` (`connection`,`queue`,`failed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `frecuencias`;
CREATE TABLE `frecuencias` (
  `frecuencia_id` int(11) NOT NULL AUTO_INCREMENT,
  `ejercicio_id` int(11) NOT NULL,
  `nombre` varchar(25) NOT NULL,
  `orden` int(11) NOT NULL,
  PRIMARY KEY (`frecuencia_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `g_registros`;
CREATE TABLE `g_registros` (
  `nsf` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `nombre` varchar(50) NOT NULL,
  `apellido` varchar(150) NOT NULL COMMENT 'separado por una coma paterno de materno',
  `segundo_apellido` varchar(50) DEFAULT NULL,
  `genero` tinyint(3) unsigned NOT NULL DEFAULT 0 COMMENT 'Masculino(0) Femenino(1)',
  `correo` varchar(154) DEFAULT NULL,
  `area_id` int(11) NOT NULL,
  `perfil` int(11) NOT NULL,
  `registro` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'unix timestamp  fecha de registro',
  `activo` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Usuario activo(1) inactivo(0)',
  `modificacion` int(10) unsigned NOT NULL DEFAULT 0,
  `validacion` tinyint(1) NOT NULL DEFAULT 0,
  `cerrado` enum('0','1') DEFAULT '0',
  PRIMARY KEY (`nsf`),
  UNIQUE KEY `correo_UNIQUE` (`correo`),
  UNIQUE KEY `correo` (`correo`)
) ENGINE=InnoDB AUTO_INCREMENT=162 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci COMMENT='Tabla de personas registradas en el sistema';


DROP TABLE IF EXISTS `indicadores`;
CREATE TABLE `indicadores` (
  `indicador_id` int(11) NOT NULL AUTO_INCREMENT,
  `meta_id` int(11) NOT NULL,
  `proyecto_id` int(11) NOT NULL,
  `unidad_medida_id` int(11) NOT NULL,
  `dimension_id` int(11) NOT NULL,
  `frecuencia_id` int(11) NOT NULL,
  `nombre` varchar(1024) NOT NULL,
  `definicion` varchar(1024) NOT NULL,
  `metodo_calculo` varchar(1024) NOT NULL,
  `meta` float NOT NULL,
  `id_metap` bigint(20) unsigned DEFAULT NULL,
  `id_metac` bigint(20) unsigned DEFAULT NULL,
  `requiere_revision` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`indicador_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7957 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `job_batches`;
CREATE TABLE `job_batches` (
  `id` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `total_jobs` int(11) NOT NULL,
  `pending_jobs` int(11) NOT NULL,
  `failed_jobs` int(11) NOT NULL,
  `failed_job_ids` longtext NOT NULL,
  `options` mediumtext DEFAULT NULL,
  `cancelled_at` int(11) DEFAULT NULL,
  `created_at` int(11) NOT NULL,
  `finished_at` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `jobs`;
CREATE TABLE `jobs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `queue` varchar(255) NOT NULL,
  `payload` longtext NOT NULL,
  `attempts` smallint(5) unsigned NOT NULL,
  `reserved_at` int(10) unsigned DEFAULT NULL,
  `available_at` int(10) unsigned NOT NULL,
  `created_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `jobs_queue_index` (`queue`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `mailing_configs`;
CREATE TABLE `mailing_configs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `host` varchar(255) DEFAULT NULL,
  `port` int(11) NOT NULL DEFAULT 587,
  `username` varchar(255) DEFAULT NULL,
  `password` text DEFAULT NULL,
  `encryption` varchar(255) NOT NULL DEFAULT 'tls',
  `from_address` varchar(255) DEFAULT NULL,
  `from_name` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `meses`;
CREATE TABLE `meses` (
  `mes_id` int(11) NOT NULL AUTO_INCREMENT,
  `nombre` varchar(25) NOT NULL,
  `small` varchar(3) NOT NULL,
  PRIMARY KEY (`mes_id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `meses_controles_metas`;
CREATE TABLE `meses_controles_metas` (
  `mes_control_meta_id` int(11) NOT NULL AUTO_INCREMENT,
  `ejercicio_id` int(11) NOT NULL,
  `mes_id` int(11) NOT NULL,
  `habilitado` char(2) NOT NULL,
  PRIMARY KEY (`mes_control_meta_id`)
) ENGINE=InnoDB AUTO_INCREMENT=205 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `meses_metas_alcanzadas`;
CREATE TABLE `meses_metas_alcanzadas` (
  `mes_meta_alcanzada_id` int(11) NOT NULL AUTO_INCREMENT,
  `meta_id` int(11) NOT NULL,
  `mes_id` int(11) NOT NULL,
  `numero` int(11) NOT NULL,
  `explicacion` text NOT NULL,
  `porcentaje` double NOT NULL DEFAULT 0,
  `porcentaje_real` double NOT NULL DEFAULT 0,
  PRIMARY KEY (`mes_meta_alcanzada_id`),
  KEY `idx_alc_meta_mes` (`meta_id`,`mes_id`)
) ENGINE=InnoDB AUTO_INCREMENT=50404 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `meses_metas_complementarias_resueltos`;
CREATE TABLE `meses_metas_complementarias_resueltos` (
  `mes_meta_programada_id` int(11) NOT NULL AUTO_INCREMENT,
  `meta_id` int(11) NOT NULL,
  `mes_id` int(11) NOT NULL,
  `numero` int(11) NOT NULL,
  PRIMARY KEY (`mes_meta_programada_id`),
  KEY `idx_comp_res_meta_mes` (`meta_id`,`mes_id`)
) ENGINE=InnoDB AUTO_INCREMENT=18481 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `meses_metas_programadas`;
CREATE TABLE `meses_metas_programadas` (
  `mes_meta_programada_id` int(11) NOT NULL AUTO_INCREMENT,
  `meta_id` int(11) NOT NULL,
  `mes_id` int(11) NOT NULL,
  `numero` int(11) NOT NULL,
  PRIMARY KEY (`mes_meta_programada_id`),
  KEY `idx_prog_meta_mes` (`meta_id`,`mes_id`),
  KEY `idx_prog_meta_mes_num` (`meta_id`,`mes_id`,`numero`)
) ENGINE=InnoDB AUTO_INCREMENT=151837 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `meses_proyectos`;
CREATE TABLE `meses_proyectos` (
  `mes_proyecto_id` int(11) NOT NULL AUTO_INCREMENT,
  `proyecto_id` int(11) NOT NULL,
  `mes_id` int(11) NOT NULL,
  `ejecuta` char(2) NOT NULL,
  PRIMARY KEY (`mes_proyecto_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11605 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `metas`;
CREATE TABLE `metas` (
  `meta_id` int(11) NOT NULL AUTO_INCREMENT,
  `meta_padre_id` bigint(20) unsigned DEFAULT NULL,
  `proyecto_id` int(11) NOT NULL,
  `unidad_medida_id` int(11) NOT NULL,
  `tipo` varchar(25) NOT NULL,
  `orden` int(11) NOT NULL,
  `nombre` varchar(1500) NOT NULL,
  `peso` double NOT NULL DEFAULT 0,
  `tmc` int(11) NOT NULL DEFAULT 1 COMMENT '0.- No 1.- Si',
  PRIMARY KEY (`meta_id`),
  KEY `idx_metas_proyecto_id` (`proyecto_id`),
  KEY `idx_metas_proyecto_orden` (`proyecto_id`,`orden`)
) ENGINE=InnoDB AUTO_INCREMENT=7251 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `migrations`;
CREATE TABLE `migrations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `migration` varchar(255) NOT NULL,
  `batch` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `model_has_permissions`;
CREATE TABLE `model_has_permissions` (
  `permission_id` bigint(20) unsigned NOT NULL,
  `model_type` varchar(255) NOT NULL,
  `model_id` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`permission_id`,`model_id`,`model_type`),
  KEY `model_has_permissions_model_id_model_type_index` (`model_id`,`model_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `model_has_roles`;
CREATE TABLE `model_has_roles` (
  `role_id` bigint(20) unsigned NOT NULL,
  `model_type` varchar(255) NOT NULL,
  `model_id` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`role_id`,`model_id`,`model_type`),
  KEY `model_has_roles_model_id_model_type_index` (`model_id`,`model_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `operacion_ejercicio_ur`;
CREATE TABLE `operacion_ejercicio_ur` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `operacion_ejercicio_id` int(11) NOT NULL,
  `unidad_responsable_gasto_id` int(11) NOT NULL,
  `habilitado` char(2) NOT NULL DEFAULT 'si',
  `fecha_prorroga` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=325 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `operaciones_ejercicios`;
CREATE TABLE `operaciones_ejercicios` (
  `operacion_ejercicio_id` int(11) NOT NULL AUTO_INCREMENT,
  `ejercicio_id` int(11) NOT NULL,
  `tipo` varchar(25) NOT NULL,
  `habilitado` char(2) NOT NULL,
  `fecha_inicio` date DEFAULT NULL,
  `fecha_fin` date DEFAULT NULL,
  PRIMARY KEY (`operacion_ejercicio_id`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `password_reset_tokens`;
CREATE TABLE `password_reset_tokens` (
  `email` varchar(255) NOT NULL,
  `token` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pei_lineas_estrategicas`;
CREATE TABLE `pei_lineas_estrategicas` (
  `pei_linea_estrategica_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `pei_programa_id` bigint(20) unsigned NOT NULL,
  `numero` tinyint(3) unsigned NOT NULL,
  `nombre` text DEFAULT NULL,
  PRIMARY KEY (`pei_linea_estrategica_id`),
  UNIQUE KEY `pei_lineas_programa_numero_unique` (`pei_programa_id`,`numero`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pei_objetivos_estrategicos`;
CREATE TABLE `pei_objetivos_estrategicos` (
  `pei_objetivo_estrategico_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `pei_linea_estrategica_id` bigint(20) unsigned NOT NULL,
  `numero` tinyint(3) unsigned NOT NULL,
  `nombre` text DEFAULT NULL,
  PRIMARY KEY (`pei_objetivo_estrategico_id`),
  UNIQUE KEY `pei_objetivos_linea_numero_unique` (`pei_linea_estrategica_id`,`numero`)
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pei_programas`;
CREATE TABLE `pei_programas` (
  `pei_programa_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `ejercicio_anio` smallint(5) unsigned NOT NULL,
  `nombre` varchar(255) NOT NULL,
  PRIMARY KEY (`pei_programa_id`),
  UNIQUE KEY `pei_programas_ejercicio_anio_unique` (`ejercicio_anio`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pei_proyecto_alineaciones`;
CREATE TABLE `pei_proyecto_alineaciones` (
  `pei_proyecto_alineacion_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `proyecto_id` int(10) unsigned NOT NULL,
  `pei_programa_id` bigint(20) unsigned NOT NULL,
  `pei_linea_estrategica_id` bigint(20) unsigned NOT NULL,
  `pei_objetivo_estrategico_id` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`pei_proyecto_alineacion_id`),
  KEY `pei_proyecto_alineaciones_pei_programa_id_foreign` (`pei_programa_id`),
  KEY `pei_proyecto_alineaciones_pei_linea_estrategica_id_foreign` (`pei_linea_estrategica_id`),
  KEY `pei_proyecto_alineaciones_pei_objetivo_estrategico_id_foreign` (`pei_objetivo_estrategico_id`)
) ENGINE=InnoDB AUTO_INCREMENT=563 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `permissions`;
CREATE TABLE `permissions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `guard_name` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `permissions_name_guard_name_unique` (`name`,`guard_name`)
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `personal_access_tokens`;
CREATE TABLE `personal_access_tokens` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `tokenable_type` varchar(255) NOT NULL,
  `tokenable_id` bigint(20) unsigned NOT NULL,
  `name` text NOT NULL,
  `token` varchar(64) NOT NULL,
  `abilities` text DEFAULT NULL,
  `last_used_at` timestamp NULL DEFAULT NULL,
  `expires_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `personal_access_tokens_token_unique` (`token`),
  KEY `personal_access_tokens_tokenable_type_tokenable_id_index` (`tokenable_type`,`tokenable_id`),
  KEY `personal_access_tokens_expires_at_index` (`expires_at`)
) ENGINE=InnoDB AUTO_INCREMENT=826 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `programas`;
CREATE TABLE `programas` (
  `programa_id` int(11) NOT NULL AUTO_INCREMENT,
  `ejercicio_id` int(11) NOT NULL,
  `numero` char(2) NOT NULL,
  `nombre` varchar(255) NOT NULL,
  PRIMARY KEY (`programa_id`),
  KEY `idx_programas_ejercicio_id` (`ejercicio_id`),
  KEY `idx_programas_ejercicio_numero` (`ejercicio_id`,`numero`)
) ENGINE=InnoDB AUTO_INCREMENT=232 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `proyecto_bitacoras`;
CREATE TABLE `proyecto_bitacoras` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `proyecto_id` int(11) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `accion` varchar(255) NOT NULL,
  `mensaje` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `proyecto_bitacoras_proyecto_id_foreign` (`proyecto_id`),
  KEY `proyecto_bitacoras_user_id_foreign` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=215 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `proyecto_bitacoras_bkp_11sep2026`;
CREATE TABLE `proyecto_bitacoras_bkp_11sep2026` (
  `id` bigint(20) unsigned NOT NULL DEFAULT 0,
  `proyecto_id` int(11) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `accion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `mensaje` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `proyectos`;
CREATE TABLE `proyectos` (
  `proyecto_id` int(11) NOT NULL AUTO_INCREMENT,
  `responsable_operativo_id` int(11) NOT NULL,
  `ejercicio_id` bigint(20) unsigned DEFAULT NULL,
  `subprograma_id` int(11) NOT NULL,
  `numero` char(3) NOT NULL,
  `nombre` varchar(1024) NOT NULL,
  `tipo` varchar(15) NOT NULL,
  `version` int(11) NOT NULL,
  `objetivo` text NOT NULL,
  `justificacion` text NOT NULL,
  `descripcion` text NOT NULL,
  `fecha` date NOT NULL,
  `nombre_responsable_operativo` varchar(255) NOT NULL,
  `cargo_responsable_operativo` varchar(512) NOT NULL,
  `nombre_titular` varchar(255) NOT NULL,
  `responsable_ficha` varchar(255) NOT NULL,
  `autorizado_por` varchar(512) NOT NULL,
  `status` varchar(15) NOT NULL DEFAULT 'abierto',
  `fecha_cierre` datetime DEFAULT NULL,
  `fecha_verificacion` timestamp NULL DEFAULT NULL,
  `puesto_responsable_ficha` varchar(255) DEFAULT NULL,
  `autorizante_nombre` varchar(255) DEFAULT NULL,
  `autorizante_puesto` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`proyecto_id`),
  KEY `idx_proyectos_subprograma_id` (`subprograma_id`),
  KEY `idx_proyectos_subprograma_numero` (`subprograma_id`,`numero`)
) ENGINE=InnoDB AUTO_INCREMENT=1807 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `puestos`;
CREATE TABLE `puestos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `usuario_poa_id` int(10) unsigned NOT NULL,
  `nombre` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `puestos_usuario_poa_id_unique` (`usuario_poa_id`)
) ENGINE=InnoDB AUTO_INCREMENT=155 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `responsables_operativos`;
CREATE TABLE `responsables_operativos` (
  `responsable_operativo_id` int(11) NOT NULL AUTO_INCREMENT,
  `unidad_responsable_gasto_id` int(11) NOT NULL,
  `ejercicio_id` bigint(20) unsigned DEFAULT NULL,
  `numero` char(2) NOT NULL,
  `nombre` varchar(255) NOT NULL,
  PRIMARY KEY (`responsable_operativo_id`)
) ENGINE=InnoDB AUTO_INCREMENT=996 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `riesgo_controles`;
CREATE TABLE `riesgo_controles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `riesgo_id` bigint(20) unsigned NOT NULL,
  `texto` text NOT NULL,
  `estado_validacion` varchar(255) NOT NULL DEFAULT 'Propuesto – pendiente de validación',
  `evidencia_tipo` varchar(255) DEFAULT NULL,
  `evidencia_referencia` varchar(255) DEFAULT NULL,
  `evidencia_periodicidad` varchar(255) DEFAULT NULL,
  `evidencia_responsable` varchar(255) DEFAULT NULL,
  `evidencia_link` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `riesgo_controles_riesgo_id_foreign` (`riesgo_id`),
  CONSTRAINT `riesgo_controles_riesgo_id_foreign` FOREIGN KEY (`riesgo_id`) REFERENCES `riesgos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1622 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `riesgo_evaluaciones_trimestrales`;
CREATE TABLE `riesgo_evaluaciones_trimestrales` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `riesgo_id` bigint(20) unsigned NOT NULL,
  `ejercicio_id` int(11) NOT NULL,
  `trimestre` int(11) NOT NULL,
  `etiqueta` varchar(255) DEFAULT NULL,
  `probabilidad` int(11) NOT NULL DEFAULT 0,
  `impacto` int(11) NOT NULL DEFAULT 0,
  `evidencia_control` text DEFAULT NULL,
  `incidencia` text DEFAULT NULL,
  `accion_mitigacion` text DEFAULT NULL,
  `estatus` varchar(255) DEFAULT NULL,
  `responsable` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `riesgo_evaluaciones_trimestrales_riesgo_id_trimestre_unique` (`riesgo_id`,`trimestre`),
  CONSTRAINT `riesgo_evaluaciones_trimestrales_riesgo_id_foreign` FOREIGN KEY (`riesgo_id`) REFERENCES `riesgos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `riesgo_indicadores`;
CREATE TABLE `riesgo_indicadores` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `riesgo_id` bigint(20) unsigned NOT NULL,
  `nombre` varchar(255) NOT NULL,
  `tipo` varchar(255) DEFAULT NULL,
  `periodicidad` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `formula` text DEFAULT NULL,
  `unidad` varchar(255) DEFAULT NULL,
  `sentido` varchar(255) DEFAULT NULL,
  `numerador` text DEFAULT NULL,
  `denominador` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `riesgo_indicadores_riesgo_id_foreign` (`riesgo_id`),
  CONSTRAINT `riesgo_indicadores_riesgo_id_foreign` FOREIGN KEY (`riesgo_id`) REFERENCES `riesgos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1410 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `riesgo_institucional_fuente`;
CREATE TABLE `riesgo_institucional_fuente` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `riesgo_institucional_id` bigint(20) unsigned NOT NULL,
  `riesgo_id` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `riesgo_institucional_fuente_riesgo_institucional_id_foreign` (`riesgo_institucional_id`),
  KEY `riesgo_institucional_fuente_riesgo_id_foreign` (`riesgo_id`),
  CONSTRAINT `riesgo_institucional_fuente_riesgo_id_foreign` FOREIGN KEY (`riesgo_id`) REFERENCES `riesgos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `riesgo_institucional_fuente_riesgo_institucional_id_foreign` FOREIGN KEY (`riesgo_institucional_id`) REFERENCES `riesgos_institucionales` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `riesgo_seguimientos_mensuales`;
CREATE TABLE `riesgo_seguimientos_mensuales` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `riesgo_id` bigint(20) unsigned NOT NULL,
  `ejercicio_id` int(11) NOT NULL,
  `mes` int(11) NOT NULL,
  `numerador` decimal(12,2) DEFAULT NULL,
  `denominador` decimal(12,2) DEFAULT NULL,
  `valor` decimal(12,2) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `riesgo_seguimientos_mensuales_riesgo_id_mes_unique` (`riesgo_id`,`mes`),
  CONSTRAINT `riesgo_seguimientos_mensuales_riesgo_id_foreign` FOREIGN KEY (`riesgo_id`) REFERENCES `riesgos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `riesgo_seguimientos_tables`;
CREATE TABLE `riesgo_seguimientos_tables` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `riesgos`;
CREATE TABLE `riesgos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `local_id` varchar(255) DEFAULT NULL,
  `area_id` varchar(255) DEFAULT NULL,
  `ejercicio_id` int(11) DEFAULT NULL,
  `objetivo` text DEFAULT NULL,
  `riesgo` text DEFAULT NULL,
  `factores` text DEFAULT NULL,
  `probabilidad` int(11) NOT NULL DEFAULT 0,
  `impacto` int(11) NOT NULL DEFAULT 0,
  `probabilidad_inicial` int(11) NOT NULL DEFAULT 0,
  `impacto_inicial` int(11) NOT NULL DEFAULT 0,
  `status` varchar(255) NOT NULL DEFAULT 'Borrador',
  `last_observation` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `efectos_consecuencias` text DEFAULT NULL,
  `factores_internos` text DEFAULT NULL,
  `factores_externos` text DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1283 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `riesgos_institucionales`;
CREATE TABLE `riesgos_institucionales` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `folio` varchar(255) NOT NULL,
  `ejercicio_id` int(11) NOT NULL,
  `objetivo` text DEFAULT NULL,
  `riesgo` text NOT NULL,
  `factores` text DEFAULT NULL,
  `probabilidad_sugerida` int(11) DEFAULT NULL,
  `impacto_sugerido` int(11) DEFAULT NULL,
  `probabilidad` int(11) DEFAULT NULL,
  `impacto` int(11) DEFAULT NULL,
  `justificacion_valoracion` text DEFAULT NULL,
  `estatus` varchar(255) NOT NULL DEFAULT 'Proyecto',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `riesgos_institucionales_folio_unique` (`folio`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `role_has_permissions`;
CREATE TABLE `role_has_permissions` (
  `permission_id` bigint(20) unsigned NOT NULL,
  `role_id` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`permission_id`,`role_id`),
  KEY `role_has_permissions_role_id_foreign` (`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `roles`;
CREATE TABLE `roles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `guard_name` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `roles_name_guard_name_unique` (`name`,`guard_name`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `s_accesos`;
CREATE TABLE `s_accesos` (
  `id_acceso` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `nsf` int(10) unsigned NOT NULL,
  `ingreso` int(10) unsigned NOT NULL DEFAULT 0,
  `salida` int(10) unsigned NOT NULL DEFAULT 0,
  `ip` varchar(16) NOT NULL DEFAULT '0',
  `dispositivo` text NOT NULL,
  `ultimaActividad` int(10) unsigned NOT NULL DEFAULT 0,
  `data` text DEFAULT NULL COMMENT 'Ultimos datos de sesion',
  `ultimaUrl` varchar(100) DEFAULT NULL COMMENT 'ultima url visitada',
  PRIMARY KEY (`id_acceso`),
  KEY `id_usuario` (`nsf`)
) ENGINE=InnoDB AUTO_INCREMENT=8929 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci COMMENT='Registro de accesos al sistema';


DROP TABLE IF EXISTS `s_control`;
CREATE TABLE `s_control` (
  `nsf` int(10) unsigned NOT NULL,
  `usuario` varchar(254) NOT NULL COMMENT 'usurario del sistema normalmente su correo electronico',
  `password` varchar(128) NOT NULL COMMENT 'hash password',
  `registro` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'unix timestamp de registro',
  `cambioPassword` int(11) NOT NULL DEFAULT 0 COMMENT 'unix timestamp vigencia para cambiar password',
  `activacion` varchar(100) DEFAULT NULL COMMENT 'cadena para reset password olvidado',
  `vigenciaActivacion` int(11) NOT NULL DEFAULT 0 COMMENT 'unix timestamp vigencia para reset password',
  `dispositivos` text DEFAULT NULL COMMENT 'registro de dispositivos permitidos para ingresar',
  `bloqueado` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'unix timestamp de bloqueo',
  `activo` tinyint(3) unsigned NOT NULL DEFAULT 0 COMMENT 'indica si el usuario esta activo(1) o bloqueado(0)',
  PRIMARY KEY (`nsf`),
  UNIQUE KEY `usuario_UNIQUE` (`usuario`),
  KEY `id_registro` (`nsf`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


DROP TABLE IF EXISTS `s_modulos`;
CREATE TABLE `s_modulos` (
  `id_modulo` int(11) NOT NULL AUTO_INCREMENT,
  `modulo` varchar(45) DEFAULT NULL,
  `controlador` varchar(256) NOT NULL,
  `activo` tinyint(1) NOT NULL,
  PRIMARY KEY (`id_modulo`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


DROP TABLE IF EXISTS `s_perfiles`;
CREATE TABLE `s_perfiles` (
  `id_perfil` tinyint(3) unsigned NOT NULL AUTO_INCREMENT,
  `perfil` varchar(50) NOT NULL,
  `activo` tinyint(3) unsigned NOT NULL DEFAULT 0 COMMENT 'activo(1) inactivo(0)',
  PRIMARY KEY (`id_perfil`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci COMMENT='Lista de perfiles de usuario del sistema';


DROP TABLE IF EXISTS `s_privilegios`;
CREATE TABLE `s_privilegios` (
  `ids_privilegios` int(11) NOT NULL AUTO_INCREMENT,
  `id_modulo` int(11) NOT NULL,
  `nsf` int(10) unsigned NOT NULL,
  `perfil` int(11) DEFAULT NULL,
  `perfil_inversiones` tinyint(4) NOT NULL DEFAULT 1 COMMENT '1.- contratos 2.- empresas 3.- obra 4.- pagos',
  `activo` int(11) DEFAULT NULL,
  `condicion` mediumtext DEFAULT NULL,
  PRIMARY KEY (`ids_privilegios`),
  KEY `fk_s_privilegios_s_modulos1_idx` (`id_modulo`),
  KEY `fk_s_privilegios_g_registros1_idx` (`nsf`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


DROP TABLE IF EXISTS `sessions`;
CREATE TABLE `sessions` (
  `id` varchar(255) NOT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `payload` longtext NOT NULL,
  `last_activity` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `sessions_user_id_index` (`user_id`),
  KEY `sessions_last_activity_index` (`last_activity`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subprograma_pei_alineaciones`;
CREATE TABLE `subprograma_pei_alineaciones` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `subprograma_id` int(10) unsigned NOT NULL,
  `pei_linea_estrategica_id` bigint(20) unsigned NOT NULL,
  `pei_objetivo_estrategico_id` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_subprograma_pei_mapping` (`subprograma_id`,`pei_linea_estrategica_id`,`pei_objetivo_estrategico_id`),
  KEY `fk_spa_linea_id` (`pei_linea_estrategica_id`),
  KEY `fk_spa_objetivo_id` (`pei_objetivo_estrategico_id`)
) ENGINE=InnoDB AUTO_INCREMENT=644 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subprogramas`;
CREATE TABLE `subprogramas` (
  `subprograma_id` int(11) NOT NULL AUTO_INCREMENT,
  `programa_id` int(11) NOT NULL,
  `ejercicio_id` bigint(20) unsigned DEFAULT NULL,
  `numero` char(2) NOT NULL,
  `nombre` varchar(255) NOT NULL,
  PRIMARY KEY (`subprograma_id`),
  KEY `idx_subprogramas_programa_id` (`programa_id`),
  KEY `idx_subprogramas_programa_numero` (`programa_id`,`numero`)
) ENGINE=InnoDB AUTO_INCREMENT=636 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `tipos_indicadores`;
CREATE TABLE `tipos_indicadores` (
  `tipo_indicador_id` int(11) NOT NULL AUTO_INCREMENT,
  `nombre` varchar(50) NOT NULL,
  `descripcion` varchar(255) NOT NULL,
  PRIMARY KEY (`tipo_indicador_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `unidades_medidas`;
CREATE TABLE `unidades_medidas` (
  `unidad_medida_id` int(11) NOT NULL AUTO_INCREMENT,
  `ejercicio_id` int(11) NOT NULL,
  `numero` char(3) NOT NULL,
  `nombre` varchar(255) NOT NULL,
  `descripcion` varchar(1024) NOT NULL,
  `porcentajes` varchar(1) NOT NULL DEFAULT '0' COMMENT '0.- No 1.- Si',
  PRIMARY KEY (`unidad_medida_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6025 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `unidades_responsables_gastos`;
CREATE TABLE `unidades_responsables_gastos` (
  `unidad_responsable_gasto_id` int(11) NOT NULL AUTO_INCREMENT,
  `ejercicio_id` int(11) NOT NULL,
  `numero` varchar(5) DEFAULT NULL,
  `nombre` varchar(255) NOT NULL,
  `repite_proyecto` char(2) NOT NULL DEFAULT 'no',
  `cerrada` enum('0','1') DEFAULT '0',
  PRIMARY KEY (`unidad_responsable_gasto_id`)
) ENGINE=InnoDB AUTO_INCREMENT=582 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `usuario_unidad_responsable`;
CREATE TABLE `usuario_unidad_responsable` (
  `usuario_poa_id` bigint(20) unsigned NOT NULL,
  `unidad_responsable_gasto_id` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`usuario_poa_id`,`unidad_responsable_gasto_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `usuarios_conectados`;
CREATE TABLE `usuarios_conectados` (
  `usuario_conectado_id` int(11) NOT NULL AUTO_INCREMENT,
  `usuario_poa_id` int(11) NOT NULL,
  `fecha` datetime NOT NULL,
  PRIMARY KEY (`usuario_conectado_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1489266 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `usuarios_ejercicios`;
CREATE TABLE `usuarios_ejercicios` (
  `id_usuario_ejercicio` int(11) NOT NULL AUTO_INCREMENT,
  `usuario_id` int(11) NOT NULL,
  `ejercicio_id` int(11) NOT NULL,
  PRIMARY KEY (`id_usuario_ejercicio`),
  KEY `usuario_id` (`usuario_id`),
  KEY `ejercicio_id` (`ejercicio_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1230 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


DROP TABLE IF EXISTS `usuarios_poa`;
CREATE TABLE `usuarios_poa` (
  `usuario_poa_id` int(11) NOT NULL AUTO_INCREMENT,
  `area_id` int(11) NOT NULL,
  `nombre` varchar(35) NOT NULL,
  `apellido_paterno` varchar(35) NOT NULL,
  `apellido_materno` varchar(35) NOT NULL,
  `sexo` varchar(10) NOT NULL DEFAULT 'hombre',
  `usuario` varchar(50) NOT NULL,
  `correo` varchar(255) DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `foto` varchar(255) NOT NULL,
  `nivel` varchar(25) NOT NULL DEFAULT 'normal',
  `ejercicio_elaboracion` int(11) NOT NULL,
  `consulta_integral` char(2) NOT NULL DEFAULT 'no',
  `captura_seguimiento` char(2) NOT NULL DEFAULT 'no',
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`usuario_poa_id`)
) ENGINE=InnoDB AUTO_INCREMENT=731 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `usuarios_responsables_operativos`;
CREATE TABLE `usuarios_responsables_operativos` (
  `usuario_responsable_operativo_id` int(11) NOT NULL AUTO_INCREMENT,
  `usuario_poa_id` int(11) NOT NULL,
  `responsable_operativo_id` int(11) NOT NULL,
  PRIMARY KEY (`usuario_responsable_operativo_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5720 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


DROP TABLE IF EXISTS `usuarios_subprogramas`;
CREATE TABLE `usuarios_subprogramas` (
  `usuario_subprograma_id` int(11) NOT NULL AUTO_INCREMENT,
  `usuario_poa_id` int(11) NOT NULL,
  `subprograma_id` int(11) NOT NULL,
  PRIMARY KEY (`usuario_subprograma_id`)
) ENGINE=InnoDB AUTO_INCREMENT=160 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


SET FOREIGN_KEY_CHECKS=1;
